//   2) «מי הקליט» = «בודק QA (QA-AUTO)» → «העלאת קובץ MP3» → выбрать arvit-ashk-k3.mp3 (Файлы) → «ממתינה לאישור — המשתמשים עדיין לא שומעים אותה.»;
//   3) USER1: ערבית 3 מתוך 15 → «אין הקראה לקטע הזה», «השמע» неактивна; 4) ADMIN: «אישור ההקראה ופרסומה» → «אושרה על ידי … — מוצעת להשמעה למשתמשים.»;
//   5) USER1: «הקראה: … · אושרה על ידי …», «השמע» → «השהה», звук слышен; 6) ADMIN: текст קטע + « א» → «שמירת טיוטה» → «אישור ופרסום» →
//   в карточке «לא תואמת את הטקסט הנוכחי של הקטע…», «אישור ההקראה ופרסומה» нет; 7) вернуть текст посимвольно и утвердить; 8) «הסרת ההקראה» → «ההקראה הוסרה.».
// @data: в finally запись удаляется, текст возвращается посимвольно, файл с телефона удаляется, аккаунт — USER1.
// ОБНОВЛЕНО 25.10.2026: полный жизненный цикл записи на СВОЁМ QA קטע («ברכת הלבנה · אשכנז», без правки чужого текста) — specs/qa-2510/q-17
//  (кейс AD-13); удаление קטע с записью — с 26.10 (#544d9c עבר QA) прямо вместе с записью, без «הסרת ההקראה» (q-18, кейс AD-14).
import fs from 'node:fs';
import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { playerButton, recordingLine } from '../_lib/app-0710.ts';
import {
  asAdmin, asUser1, backToUser1, openAdminPrayer, openSection, reopenSection, setBody, saveDraft, approveDraft,
  restoreSectionText, origArvit3, qaMarker, openUserArvit3, qaFile, pushToDownloads, removeFromDevice,
  removeRecordingIfAny, recordingSummary,
  REC_CARD, REC_NONE, REC_PENDING, REC_APPROVE_BTN, REC_APPROVED_RE, REC_NOT_MATCHING, REC_REMOVED,
} from '../_lib/admin.ts';
import { uploadRecordingAny } from '../_lib/app-1310.ts';

const PRAYER = 'ערבית', NUSACH = 'אשכנז', SECTION = 'המעריב ערבים';
const FILE = 'arvit-ashk-k3.mp3';
const RECORDED_BY = 'בודק QA (QA-AUTO)';

describe('Админка в приложении: запись קטע (MP3)', () => {
  afterEach(async () => { await toHome(); });

  it('AD-07 «המעריב ערבים»: «מי הקליט» → MP3 → «ממתינה לאישור» (USER1: нет) → утвердить (USER1: «הקראה: … · אושרה על ידי …», играет) → правка текста → «לא תואמת» → текст назад → «הסרת ההקראה» #6a86f7ed9d38 #6a86f7eda7b2 @data @cleanup @manual-check', async function () {
    const orig = origArvit3();
    let remote = '';
    try {
      if (driver.isAndroid) remote = await pushToDownloads(FILE, fs.readFileSync(qaFile('research/rec-pages/arvit-ashk-k3.mp3')).toString('base64'));
      await asAdmin();

      // 0. Исходно у קטע 3 записи нет (иначе — остаток прошлого прогона; уберём в finally и упадём здесь).
      await openAdminPrayer(PRAYER, NUSACH);
      const before = await recordingSummary();
      await openSection(SECTION);
      await scrollToText(REC_CARD);
      await expect(await scrollToText(REC_NONE)).toBeDisplayed();

      // 1. «מי הקליט» → «העלאת קובץ MP3» → файл → «ממתינה לאישור — המשתמשים עדיין לא שומעים אותה.» и «אישור ההקראה ופרסומה» (rec-A2).
      await uploadRecordingAny(FILE, RECORDED_BY);
      await (await byTextContains(REC_PENDING)).waitForDisplayed({ timeout: 180000 });
      await expect(byTextContains(`הוקלט על ידי ${RECORDED_BY}`)).toBeDisplayed();
      await expect(await scrollToText(REC_APPROVE_BTN)).toBeDisplayed();

      // 2. USER1: в קטע 3 «אין הקראה לקטע הזה», строки «הקראה:» нет (rec-B, F-92 AC1/AC4).
      await asUser1();
      await openUserArvit3();
      await scrollToText('האזן להקראה');
      await expect(await scrollToText('אין הקראה לקטע הזה')).toBeDisplayed();
      await expect(recordingLine()).not.toBeDisplayed();

      // 3. ADMIN: «אישור ההקראה ופרסומה» → «אושרה על ידי … — מוצעת להשמעה למשתמשים.» (rec-C); в сводке +1 «מאושרות».
      await asAdmin();
      await reopenSection(PRAYER, NUSACH, SECTION);
      await (await scrollToText(REC_APPROVE_BTN)).click();
      await (await byTextMatches(REC_APPROVED_RE)).waitForDisplayed({ timeout: 30000 });
      await openAdminPrayer(PRAYER, NUSACH);
      expect((await recordingSummary()).approved).toBe(before.approved + 1);

      // 4. USER1: «הקראה: <מי הקליט> · אושרה על ידי <имя>»; «השמע» → «השהה» (играет), «השהה» → «השמע» (rec-D1/D2).
      await asUser1();
      await openUserArvit3();
      await scrollToText('האזן להקראה');
      await expect(recordingLine()).toHaveText(new RegExp(`הקראה: .*QA-AUTO.* · אושרה על ידי .+`));
      await expect(byText('אין הקראה לקטע הזה')).not.toBeDisplayed();
      await (await playerButton('השמע')).click();
      await expect(await playerButton('השהה')).toBeDisplayed();
      await (await playerButton('השהה')).click();
      await expect(await playerButton('השמע')).toBeDisplayed();

      // 5. ADMIN: правка текста (« א») → «שמירת טיוטה» → «אישור ופרסום» → запись «לא תואמת…», утвердить её нельзя (rec-F1/F2, F-92 AC2).
      await asAdmin();
      await reopenSection(PRAYER, NUSACH, SECTION);
      await setBody(orig + ' א');
      await saveDraft();
      await approveDraft(qaMarker('ad07-text'));
      expect((await recordingSummary()).notMatching).toBe(before.notMatching + 1);
      await openSection(SECTION);
      await scrollToText(REC_CARD);
      await expect(await scrollToText(REC_NOT_MATCHING)).toBeDisplayed();
      await expect(byText(REC_APPROVE_BTN)).not.toBeDisplayed();

      // 6. USER1: в קטע 3 запись не предлагается — «אין הקראה לקטע הזה» (rec-F3).
      await asUser1();
      await openUserArvit3();
      await scrollToText('האזן להקראה');
      await expect(await scrollToText('אין הקראה לקטע הזה')).toBeDisplayed();
      await expect(recordingLine()).not.toBeDisplayed();

      // 7. ADMIN: вернуть текст посимвольно; затем «הסרת ההקראה» → «ההקראה הוסרה.» и «לקטע הזה אין עדיין הקראה.» (rec-G1).
      await asAdmin();
      await restoreSectionText(PRAYER, NUSACH, SECTION, orig, 'ad07');
      expect(await removeRecordingIfAny()).toBe(true);
      await expect(byTextContains(REC_REMOVED)).toBeDisplayed();
      await expect(byTextContains(REC_NONE)).toBeDisplayed();
      await openAdminPrayer(PRAYER, NUSACH);
      expect(await recordingSummary()).toEqual(before);
    } finally {
      try {
        if (remote) await removeFromDevice(remote);
        await asAdmin().catch(() => {});
        await restoreSectionText(PRAYER, NUSACH, SECTION, orig, 'ad07');
        await removeRecordingIfAny();
      } finally {
        await backToUser1();
      }
    }
  });
});
